interface Request { type: string; payload: any }
interface Handler { setNext(next: Handler): void; handle(req: Request): boolean }
class BaseHandler implements Handler {
  private next?: Handler
  setNext(next: Handler) { this.next = next }
  handle(req: Request): boolean {
    if (this.canHandle(req)) { /* process */ return true }
    return this.next ? this.next.handle(req) : false
  }
  protected canHandle(req: Request) { return false }
}

